[AllowAnonymous, HttpPost("forgot-password")]
public async Task<IActionResult> ForgotPassword(ForgotPasswordDto dto)
{
    var user = await _users.FindByEmailAsync(dto.Email);
    if (user is not null && await _users.IsEmailConfirmedAsync(user))
    {
        var token = await _users.GeneratePasswordResetTokenAsync(user);
        await _emailQueue.EnqueueResetLinkAsync(user, token);   // queued, so timing doesn't leak
    }
    return Ok(new { message = "If that address is registered, a reset link has been sent." });
}

public sealed class MinimumAgeRequirement(int age) : IAuthorizationRequirement
{
    public int Age { get; } = age;
}

public sealed class MinimumAgeHandler : AuthorizationHandler<MinimumAgeRequirement>
{
    protected override Task HandleRequirementAsync(AuthorizationHandlerContext ctx, MinimumAgeRequirement req)
    {
        var dob = ctx.User.FindFirst(ClaimTypes.DateOfBirth)?.Value;
        if (dob is not null &&
            DateOnly.Parse(dob).AddYears(req.Age) <= DateOnly.FromDateTime(DateTime.UtcNow))
        {
            ctx.Succeed(req);
        }
        return Task.CompletedTask;   // no Succeed = not met here (another handler may still succeed)
    }
}

builder.Services.AddSingleton<IAuthorizationHandler, MinimumAgeHandler>();
builder.Services.AddAuthorizationBuilder()
    .AddPolicy("AtLeast21", p => p.AddRequirements(new MinimumAgeRequirement(21)));

