public sealed class TaskOwnerHandler : AuthorizationHandler<OperationAuthorizationRequirement, TaskItem>
{
    protected override Task HandleRequirementAsync(AuthorizationHandlerContext ctx,
        OperationAuthorizationRequirement op, TaskItem task)
    {
        var userId = ctx.User.FindFirst("sub")?.Value;
        if (userId == task.OwnerId.ToString() || ctx.User.IsInRole("Admin"))
            ctx.Succeed(op);
        return Task.CompletedTask;
    }
}

