public sealed class PermissionClaimsTransformation(IPermissionCache cache) : IClaimsTransformation
{
    public async Task<ClaimsPrincipal> TransformAsync(ClaimsPrincipal principal)
    {
        if (principal.HasClaim(c => c.Type == "perm")) return principal;   // idempotent
        var userId = principal.FindFirst("sub")?.Value;
        if (userId is null) return principal;

        var extra = new ClaimsIdentity();
        foreach (var p in await cache.GetPermissionsAsync(userId))        // cached, not a DB hit per request
            extra.AddClaim(new Claim("perm", p));
        principal.AddIdentity(extra);
        return principal;
    }
}

