public sealed class ApiKeyHandler(IOptionsMonitor<AuthenticationSchemeOptions> options,
    ILoggerFactory logger, UrlEncoder encoder, IApiKeyStore store)
    : AuthenticationHandler<AuthenticationSchemeOptions>(options, logger, encoder)
{
    protected override async Task<AuthenticateResult> HandleAuthenticateAsync()
    {
        if (!Request.Headers.TryGetValue("X-Api-Key", out var key))
            return AuthenticateResult.NoResult();

        var client = await store.FindByHashAsync(Sha256Hex(key.ToString()));   // compare hashes, not raw keys
        if (client is null) return AuthenticateResult.Fail("Invalid API key");

        var identity = new ClaimsIdentity(new[]
        {
            new Claim("client_id", client.Id),
            new Claim("scope", client.Scopes)
        }, Scheme.Name);
        return AuthenticateResult.Success(new AuthenticationTicket(new ClaimsPrincipal(identity), Scheme.Name));
    }

    private static string Sha256Hex(string value) =>
        Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)));
}
